package com.hsm.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class SessionFilter extends OncePerRequestFilter { public static final String USER="hsm.user"; private final SessionService sessions; public SessionFilter(SessionService s){sessions=s;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String t=r.getHeader("Authorization");if(t!=null&&t.startsWith("Bearer "))try{r.setAttribute(USER,sessions.require(t.substring(7)));}catch(RuntimeException ignored){} c.doFilter(r,p);} }
